1.7 Use Reduce for functional programming
This is the parallel version but applying to tidyplots.

library(tidyplots)

add_points_curve &lt;- function(x, y, ...) {
  Reduce(
    f = function(init_plot, next_component) {next_component(init_plot)},
    x = list(...),
    init = ggplot2::mpg |&gt; 
      tidyplot(x = {{x}}, y = {{y}}) |&gt; 
      add_title(title = "p0"),
    accumulate = TRUE
  )
}

add_points_curve(
  x = displ,
  y = hwy,
  function(plot) {
    add_data_points_beeswarm(plot, alpha = 0.4) |&gt; 
    adjust_title(title = "p1")
  },
  function(plot) {
    add_curve_fit(plot, fill = "#bb5566") |&gt; 
    adjust_title(title = "p2")
  }
) |&gt; 
  patchwork::wrap_plots(ncol = 3)

`geom_smooth()` using formula = 'y ~ x'

1.8 Character vs. object/argument
I confess I asked ChatGPT because it is abstract to me.

library(tidyplots)

df &lt;- tibble::tibble(
  a = letters[1:5],
  b = 1:5
)
df

# A tibble: 5 × 2
  a         b
  &lt;chr&gt; &lt;int&gt;
1 a         1
2 b         2
3 c         3
4 d         4
5 e         5


Represent column via character.

x &lt;- "a"

p1 &lt;- df |&gt; 
  tidyplot(
    x = a, 
    y = b, 
    color = a
  ) |&gt; 
  add_sum_bar() |&gt; 
  add_title(title = "p1: ordinary way")
p1







rlang::sym(x) # change it to an object

a

p2 &lt;- df |&gt; 
  tidyplot(
    x = !!rlang::sym(x), 
    y = b, 
    color = !!rlang::sym(x) # sym: symbol
  ) |&gt; 
  add_sum_bar() |&gt; 
  add_title(title = "p2: via 'rlang::sym()'")
p2









sym() take string as input and turn it into symbol. Symbol is a kind of defused expression that represent object in environment.


p3 &lt;- df |&gt; 
  tidyplot(
    x = .data[[x]], 
    y = b, 
    color = .data[[x]]
  ) |&gt; 
  add_sum_bar() |&gt; 
  add_title(title = "p3: via '.data[[x]]'")
p3








By the way, if we want to add a new column (i.e. ab) to df, we could:

# Ordinary way 1
df |&gt; 
  dplyr::mutate(ab = 11:15)

