2 b         2    12
3 c         3    13
4 d         4    14
5 e         5    15

# Way 2
df |&gt; 
  dplyr::mutate(
    !!paste0(x, "b") := 11:15
  )

# A tibble: 5 × 3
  a         b    ab
  &lt;chr&gt; &lt;int&gt; &lt;int&gt;
1 a         1    11
2 b         2    12
3 c         3    13
4 d         4    14
5 e         5    15

# Way 3
add_a_new_column &lt;- function(df, new_column) {
  df_new &lt;- df |&gt; 
    dplyr::mutate(
      !!paste0(rlang::as_name(rlang::enquo(new_column)), "b") := 11:15
    )

  print(rlang::enquo(new_column)) # defuse function argument

  print(rlang::as_name(rlang::enquo(new_column))) # extract name from a symbol

  return(df_new)
}

add_a_new_column(df = df, new_column = a)

