Last, invoke plot via function:

plot1 &lt;- function(df, x_column) {
  p &lt;- df |&gt; 
    tidyplot(x = {{ x_column }}, y = b, color = {{ x_column }}) |&gt; 
    add_sum_bar()

  return(p)
}
plot1(df, x_column = a)







plot2 &lt;- function(df, x_column) {
  p &lt;- df |&gt; 
    tidyplot(x = !!rlang::sym(x_column), y = b, color = !!rlang::sym(x_column)) |&gt; 
    add_sum_bar()

  return(p)
}
plot2(df, x_column = "a")







plot3 &lt;- function(df, x_column) {
  p &lt;- df |&gt; 
    tidyplot(x = .data[[x_column]], y = b, color = .data[[x_column]]) |&gt; 
    add_sum_bar()

  return(p)
}
