1.9 Add percent annotation
Suppose I have a proportion of 0.15 (i.e. 15%), and I want to put it somewhere in a plot with “15.0%”.

library(tidyplots)

df &lt;- tibble::tibble(
  x = 1,
  y = 1,
  label = 0.15
)

p0 &lt;- df |&gt; 
  tidyplot(x = x, y = y) |&gt; 
  add_data_points() 

p1 &lt;- p0 |&gt; 
  add_data_labels(label = label) |&gt; 
  add_title(title = "p1")

p2 &lt;- p0 |&gt; 
  add_title(title = "p2: via scales::number()") |&gt; 
  add_data_labels(
    label = scales::number(
      label, 
      scale = 100, # label * 100
      accuracy = 0.1,
      suffix = "%"      
    )
  )

p3 &lt;- p0 |&gt; 
  add_title(title = "p3: via paste0") |&gt; 
  add_data_labels(
    label = paste0(
      label * 100,
      ".0%"
    )
  )

p4 &lt;- df |&gt; 
  dplyr::mutate(
    label = scales::number( # should also be possible via `paste0`
      label, 
      scale = 100, # label * 100
      accuracy = 0.1,
      suffix = "%"      
    )
  ) |&gt; 
  tidyplot(x = x, y = y) |&gt; 
  add_data_points() |&gt; 
  add_data_labels(label = label) |&gt; 
  add_title(title = "p4: via dplyr::mutate() and scales::number()")

patchwork::wrap_plots(p1, p2, p3, p4)

1.11 How long does my junior high school daughter sleep on weekdays?

library(tidyplots)

df &lt;- tibble::tibble(
  sleep_at = lubridate::ymd_hm(
    paste(
      Sys.Date(), 
      "23:30", 
      sep = " ")
    ), # the deadline, sometimes earlier
  get_up_at = lubridate::ymd_hm(
    paste(
      Sys.Date() + 1, 
      "6:50", 
      sep = " ")
    ), # fixed time
  seconds = (get_up_at - sleep_at) |&gt; 
    lubridate::as.duration(),
  hours = seconds / 3600, # 3600s per hour
  sleep_duration = "sleep_duration"
)
df

# A tibble: 1 × 5
  sleep_at            get_up_at           seconds              hours            
  &lt;dttm&gt;              &lt;dttm&gt;              &lt;Duration&gt;           &lt;Duration&gt;       
1 2026-11-25 23:30:00 2026-11-26 06:50:00 26400s (~7.33 hours) 7.33333333333333s
# ℹ 1 more variable: sleep_duration &lt;chr&gt;

df |&gt; 
  tidyplot(x = sleep_duration, y = hours) |&gt; 
  add_sum_bar() |&gt; 
  add_sum_value(fontsize = 12) |&gt; 
  remove_x_axis_labels() |&gt; 
  add_caption(caption = "7.3h means 7h 18min, not 7h 30min")








Sleeping at 23:30 does not mean finishing homework at that time. It simply means that the student (grade 9) might be used to going to bed at that time.
